using System;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using Demo5.FrontEnd;
public static class VerifyFacilityContours {
 static SettlementController C()=>UnityEngine.Object.FindAnyObjectByType<SettlementController>();
 static async Task Tap(Button b){await Task.Delay(100);Canvas.ForceUpdateCanvases();if(!b.IsActive()||!b.IsInteractable())throw new Exception("Unavailable "+b.name);var r=(RectTransform)b.transform;var cam=b.GetComponentInParent<Canvas>().worldCamera;Vector2 pos=RectTransformUtility.WorldToScreenPoint(cam,r.TransformPoint(r.rect.center));var f=b.GetComponent<SettlementFacilityFocus>();if(f&&!f.IsRaycastLocationValid(pos,cam)){bool found=false;for(int y=1;y<10&&!found;y++)for(int x=1;x<10&&!found;x++){var test=RectTransformUtility.WorldToScreenPoint(cam,r.TransformPoint(new Vector3(r.rect.width*x/10,-r.rect.height*y/10,0)));if(f.IsRaycastLocationValid(test,cam)){pos=test;found=true;}}if(!found)throw new Exception("No hit polygon");}var e=new PointerEventData(EventSystem.current){position=pos,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<Button>()!=b)throw new Exception("Blocked "+b.name);ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerClickHandler);await Task.Delay(150);}
 public static async Task<string> Run(){var c=C();c.Workbench.GetComponent<SettlementFacilityFocus>().OnPointerExit(null);await Tap(c.Bed);await Tap(c.WorkPanel.CloseButton);await Tap(c.Stock);await Tap(c.CookingPanel.IsOpen?c.CookingPanel.Back:c.CraftPanel.CloseButton);await Tap(c.Workbench);await Tap(c.CraftPanel.CloseButton);await Tap(c.Cabinet);await Tap(c.InventoryPanel.CloseButton);await Tap(c.Exit);await Tap(c.ExpeditionPanel.Back);if(c.Development.ResearchButton.IsActive()){await Tap(c.Development.ResearchButton);await Tap(c.CraftPanel.CloseButton);}EventSystem.current.SetSelectedGameObject(null);await Task.Delay(100);var fs=c.Main.GetComponentsInChildren<SettlementFacilityFocus>();if(fs.Any(f=>f.Caption.activeSelf||f.Focus.activeSelf))throw new Exception("Old overlay visible");var lines=UnityEngine.Object.FindObjectsByType<LineRenderer>(FindObjectsSortMode.None).Where(l=>l.name.StartsWith("Facility contour")).ToArray();if(lines.Length==0||lines.Any(l=>l.sortingOrder>=c.StandeeBodies.Min(s=>s.sortingOrder)))throw new Exception("Not behind characters");var f=c.Workbench.GetComponent<SettlementFacilityFocus>();f.OnPointerEnter(null);await Task.Delay(100);if(!f.Help.text.Contains("작업대")||!lines.Any(l=>l.startColor.a>.8f))throw new Exception("Hover failed");f.OnPointerExit(null);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.LeftAlt));await Task.Delay(200);if(lines.Where(l=>l.enabled).Any(l=>l.startColor.a<.8f))throw new Exception("Alt failed");InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());await Task.Delay(200);if(lines.Where(l=>l.enabled).Any(l=>l.startColor.a>.4f))throw new Exception("Highlight stuck");return "PASS 5 furniture polygon clicks, panels close, old overlays hidden, hover/footer, Alt press/release and render order behind survivors. "+lines.Length+" contour paths.";}
}

